import zipfile, os

with zipfile.ZipFile('/tmp/scogs_animals.zip', 'r') as zf:
    mafft_files = sorted([f for f in zf.namelist() if f.endswith('.mafft')])

    # Count sequences per alignment
    seq_counts = {}
    for mf in mafft_files:
        content = zf.read(mf).decode('utf-8')
        nseqs = content.count('>')
        seq_counts[nseqs] = seq_counts.get(nseqs, 0) + 1

    print('Sequence count distribution:')
    for k in sorted(seq_counts.keys()):
        print(f'  {k} sequences: {seq_counts[k]} alignments')

    # Find alignments with 4 sequences and test PIS
    four_seq = []
    for mf in mafft_files:
        content = zf.read(mf).decode('utf-8')
        if content.count('>') == 4:
            four_seq.append(mf)
            if len(four_seq) >= 5:
                break

    print(f'\nFirst {len(four_seq)} alignments with 4 sequences:')
    for mf in four_seq:
        content = zf.read(mf).decode('utf-8')
        sequences = []
        current_seq = []
        current_id = None
        for line in content.split('\n'):
            line = line.strip()
            if line.startswith('>'):
                if current_id is not None:
                    sequences.append(''.join(current_seq))
                current_id = line
                current_seq = []
            elif line:
                current_seq.append(line)
        if current_id is not None:
            sequences.append(''.join(current_seq))

        aln_len = len(sequences[0]) if sequences else 0
        pis_count = 0
        for col in range(aln_len):
            chars = [s[col] for s in sequences if col < len(s)]
            freq = {}
            for c in chars:
                if c not in ('-', 'X', 'x', '?', '.'):
                    freq[c] = freq.get(c, 0) + 1
            informative_chars = sum(1 for count in freq.values() if count >= 2)
            if informative_chars >= 2:
                pis_count += 1

        gene = os.path.splitext(os.path.basename(mf))[0]
        print(f'  {gene}: {len(sequences)} seqs, {aln_len} cols, {pis_count} PIS')
" 2>&1

